
const studentForm = document.getElementById("studentForm");
const studentTable = document.getElementById("studentTable");
const searchInput = document.getElementById("searchInput");
const totalStudents = document.getElementById("totalStudents");

let students = [];

// Get student data from backend
async function loadStudents() {
    try {
        const response = await fetch("/api/students");

        if (!response.ok) {
            throw new Error("Unable to load students");
        }

        students = await response.json();

        displayStudents(students);
    } catch (error) {
        alert(error.message);
    }
}

// Display students in table
function displayStudents(data) {
    studentTable.innerHTML = "";

    totalStudents.textContent = students.length;

    document.getElementById("emptyMessage").hidden = data.length !== 0;

    data.forEach(student => {
        const row = document.createElement("tr");

        const values = [
            student.id,
            student.name,
            student.email,
            student.phone || "",
            student.department || "",
            student.year || "",
            student.gender || ""
        ];

        values.forEach(value => {
            const cell = document.createElement("td");
            cell.textContent = value;
            row.appendChild(cell);
        });

        const actionCell = document.createElement("td");

        const editButton = document.createElement("button");
        editButton.textContent = "Edit";
        editButton.className = "edit-btn";
        editButton.onclick = () => editStudent(student.id);

        const deleteButton = document.createElement("button");
        deleteButton.textContent = "Delete";
        deleteButton.className = "delete-btn";
        deleteButton.onclick = () => deleteStudent(student.id);

        actionCell.append(editButton, deleteButton);
        row.appendChild(actionCell);

        studentTable.appendChild(row);
    });
}

// Add or update student
studentForm.addEventListener("submit", async function(event) {
    event.preventDefault();

    const id = document.getElementById("studentId").value;

    const student = {
        name: document.getElementById("name").value.trim(),
        email: document.getElementById("email").value.trim(),
        phone: document.getElementById("phone").value.trim(),
        department: document.getElementById("department").value,
        year: document.getElementById("year").value,
        gender: document.getElementById("gender").value
    };

    try {
        const response = await fetch(
            id ? `/api/students/${id}` : "/api/students",
            {
                method: id ? "PUT" : "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify(student)
            }
        );

        const result = await response.json();

        if (!response.ok) {
            throw new Error(result.message || "Operation failed");
        }

        alert(result.message);

        studentForm.reset();
        resetForm();
        loadStudents();

    } catch (error) {
        alert(error.message);
    }
});

// Edit student
function editStudent(id) {
    const student = students.find(s => s.id === id);

    if (!student) return;

    document.getElementById("studentId").value = student.id;
    document.getElementById("name").value = student.name;
    document.getElementById("email").value = student.email;
    document.getElementById("phone").value = student.phone || "";
    document.getElementById("department").value = student.department || "";
    document.getElementById("year").value = student.year || "";
    document.getElementById("gender").value = student.gender || "";

    document.getElementById("formTitle").textContent = "Update Student";
    document.getElementById("submitBtn").textContent = "Update Student";
    document.getElementById("cancelBtn").hidden = false;

    window.scrollTo({ top: 0, behavior: "smooth" });
}

// Delete student
async function deleteStudent(id) {
    const confirmDelete = confirm(
        "Are you sure you want to delete this student?"
    );

    if (!confirmDelete) return;

    try {
        const response = await fetch(`/api/students/${id}`, {
            method: "DELETE"
        });

        const result = await response.json();

        if (!response.ok) {
            throw new Error(result.message || "Delete failed");
        }

        alert(result.message);
        await loadStudents();

    } catch (error) {
        alert(error.message);
    }
}

// Reset form
function resetForm() {
    document.getElementById("studentId").value = "";
    document.getElementById("formTitle").textContent = "Add New Student";
    document.getElementById("submitBtn").textContent = "Add Student";
    document.getElementById("cancelBtn").hidden = true;
}

// Cancel edit
document.getElementById("cancelBtn").addEventListener("click", () => {
    studentForm.reset();
    resetForm();
});

// Search students
searchInput.addEventListener("input", function() {
    const searchText = this.value.toLowerCase();

    const filteredStudents = students.filter(student =>
        [
            student.name,
            student.email,
            student.department,
            student.id
        ].some(value =>
            String(value || "").toLowerCase().includes(searchText)
        )
    );

    displayStudents(filteredStudents);
});

// Load records when page opens
loadStudents();
